/* Ironlog — Google Drive sync, the job: merge this phone and the backup file,
   run the migrations on what came in, write the backup and the readable
   summary, and keep the Settings sync line current. The Drive calls and the
   merge itself stay in database.js. Split out (ROADMAP E17 phase 4) because
   the summary and the post-merge clean-up need the features. */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { aiKey } from './ai.js';
import { $, APP_VERSION, U, addDaysISO, esc, fmtDate, iso, nice, relDay, today, wt } from './core.js';
import { GOOGLE_CLIENT_ID, SYNC_FILE, SYNC_FORMAT, SYNC_FROM_SETTINGS, SYNC_LOCAL_SETTINGS, SYNC_V, driveClientId,
  driveDisconnect, driveFind, driveRead, driveToken, driveTokenValid, driveWrite, driveWriteNamed, mergeSync, save,
  setSyncMeta, syncKnown, syncLocalData, syncMeta } from './database.js';
import { bustCatalogue, exName } from './exercises.js';
import { closeModal, confirmDlg, modal, render, toast } from './kit.js';
import { places } from './loading.js';
import { healCustomMovements, runDataMigrations } from './migrate.js';
import { reportData, reportText } from './report.js';
import { DEFAULT_STATE, S } from './state.js';
