/* ---------------- Drive sync ---------------- */
/* A readable companion to the backup, rewritten on every sync: the last four
   weeks in plain text — every set with RIR and bar speed, daily check-ins,
   goals and the week ahead. Small enough to open on a phone, or for Claude to
   read through the Drive connector; the backup stays the source of truth. */
const SYNC_SUMMARY = 'Ironlog summary.md';
function driveSummaryText() {
  const to = today(), from = addDaysISO(to, -27);
  const R = reportData(from, to, { warm: true, notes: true, vbt: true });
  const d = s => fmtDate(s, { weekday: 'short', day: 'numeric', month: 'short' });
  const out = [`# Ironlog summary`, `Written ${new Date().toISOString().slice(0, 16).replace('T', ' ')} UTC by Ironlog ${APP_VERSION}. Last 28 days. Weights in ${U()}; "@ 2" = 2 reps in reserve (RIR). Bar-speed notes in [brackets]: best m/s, velocity loss, the sensor's RIR, and each rep's speed. The full record is "${SYNC_FILE}".`, ''];
  const cis = S.checkins.filter(c => c.date >= from && c.date <= to).sort((a, b) => a.date < b.date ? 1 : -1);
  if (cis.length) {
    out.push('## Check-ins (newest first)');
    cis.forEach(c => {
      const bits = [c.weight > 0 ? `${wt(c.weight)}` : '', c.sleepH > 0 ? `sleep ${nice(c.sleepH)} h` : '',
        ...Object.entries(c).filter(([k, v]) => !['date', 'weight', 'sleepH', 'kcal', 'notes', 'mt'].includes(k) && v != null && v !== '' && typeof v !== 'object').map(([k, v]) => `${k} ${v}`),
        c.notes ? `“${c.notes}”` : ''].filter(Boolean);
      out.push(`- ${d(c.date)}: ${bits.join(' · ') || '—'}`);
    });
    out.push('');
  }
  const goals = S.goals || [];
  if (goals.length) {
    out.push('## Goals');
    goals.forEach(g => { const cur = goalCurrent(g); out.push(`- ${g.name}: ${cur != null ? (g.type === 'sessions' ? cur : wt(cur)) : '—'} of ${g.type === 'sessions' ? g.target : wt(g.target)}${g.deadline ? ` by ${d(g.deadline)}` : ''}`); });
    out.push('');
  }
  const miss = (S.misses || []).filter(m => m.date >= from && m.date <= to).sort((a, b) => a.date < b.date ? 1 : -1);
  const unlogged = S.workouts.filter(w => w.status === 'planned' && w.date >= from && w.date < to).sort((a, b) => a.date < b.date ? 1 : -1);
  if (miss.length || unlogged.length) {
    out.push('## Missed sessions (newest first)');
    miss.forEach(m => out.push(`- ${d(m.date)} · ${m.name}${m.prog ? ` (${programName(m.prog)})` : ''}: ${m.movedTo ? 'moved' : 'skipped'} — ${missText(m)}`));
    unlogged.forEach(w => out.push(`- ${d(w.date)} · ${w.name}${w.prog ? ` (${programName(w.prog)})` : ''}: planned, nothing logged, no reason given`));
    if (miss.length) {
      const by = {};
      miss.forEach(m => { by[m.reason] = (by[m.reason] || 0) + 1; });
      out.push(`- By reason: ${Object.entries(by).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${missLabel(k)} ${n}`).join(', ')}`);
    }
    out.push('');
  }
  const ahead = S.workouts.filter(w => w.status === 'planned' && w.date >= to && w.date <= addDaysISO(to, 7)).sort((a, b) => a.date < b.date ? -1 : 1);
  if (ahead.length) {
    out.push('## Next 7 days (planned)');
    ahead.forEach(w => out.push(`- ${d(w.date)} · ${w.name}${w.prog ? ` (${programName(w.prog)})` : ''}: ${w.exercises.map(e => `${exName(e)} ${e.sets.length}×${e.sets[0] && e.sets[0].r ? e.sets[0].r : '?'}`).join(', ')}`));
    out.push('');
  }
  out.push(reportText(R));
  return out.join('\n');
}
/* One sync: read the file, merge, apply, write back. `interactive` may show
   Google's sign-in; otherwise it only runs on a token this session already has. */
let syncBusy = false;
export async function driveSync(interactive) {
  if (syncBusy) return null;
  syncBusy = true;
  try {
    const token = await driveToken(interactive);
    if (!token) return null;
    const meta = syncMeta();
    let fileId = meta.fileId || await driveFind(token);
    let remote = fileId ? await driveRead(token, fileId) : null;
    if (remote === undefined) { fileId = await driveFind(token); remote = fileId ? await driveRead(token, fileId) : null; }
    if (remote && remote.format !== SYNC_FORMAT) throw new Error(`"${SYNC_FILE}" in your Drive isn't an Ironlog sync file`);
    if (remote && remote.v > SYNC_V) throw new Error('Your Drive backup was made by a newer Ironlog — update this one first');
    const local = syncLocalData(), now = Date.now();
    /* A file written before 0.96.5 has places and the calibration only inside
       its settings: read them from there, so they merge in rather than read
       as missing (no tombstones come with them). */
    const rdata = remote && remote.data ? { ...remote.data } : null;
    if (rdata && rdata.settings) SYNC_FROM_SETTINGS.forEach(k => { if (rdata[k] === undefined && rdata.settings[k] != null) rdata[k] = rdata.settings[k]; });
    let m = mergeSync(local, rdata, remote && remote.tomb, meta.known, now);
    // safety valve: a big deletion here is asked about, never assumed
    const knownN = Object.values(meta.known || {}).reduce((n, a) => n + a.length, 0);
    if (m.localDeletes.length > 5 && m.localDeletes.length > knownN / 4) {
      const keep = await new Promise(res => {
        let done = false;
        const pickIt = v => { if (!done) { done = true; res(v); } };
        modal({
          title: 'Records missing on this phone',
          body: `<p style="margin:0;color:var(--dim)">This phone has ${m.localDeletes.length} fewer records than at its last sync. If you deleted them here, remove them from your Drive backup too. If not, put them back.</p>`,
          foot: `<button class="btn primary" id="svKeep">Put them back</button><button class="btn danger" id="svDrop">Remove from Drive</button>`,
          onClose: () => pickIt(true),     // closed without choosing: the safe answer
          onOpen: bg => {
            $('#svKeep', bg).onclick = () => { pickIt(true); closeModal(); };
            $('#svDrop', bg).onclick = () => { pickIt(false); closeModal(); };
          },
        });
      });
      if (keep) m = mergeSync(local, rdata, remote && remote.tomb, meta.known, now, { keepMissing: true });
    }
    const before = { w: S.workouts.length, c: S.checkins.length };
    const merged = { ...m.data }, fromSettings = {};
    SYNC_FROM_SETTINGS.forEach(k => { fromSettings[k] = merged[k]; delete merged[k]; });
    Object.assign(S, merged);
    bustCatalogue(); healCustomMovements();   // custom exercises may have come in; ones a backup never carried are rebuilt from the sets
    /* a phone that hasn't updated yet can still send sets under an old custom
       id; they move over the same way (and only if there are any) */
    await runDataMigrations(S, ['legacy-movements-0.96.0', 'trap-handles-0.98.0']);
    const fresh = !local.workouts.length && !local.checkins.length;
    if (remote && remote.data && remote.data.settings && fresh) {
      const keep = {}; SYNC_LOCAL_SETTINGS.forEach(k => { if (k in S.settings) keep[k] = S.settings[k]; });
      S.settings = Object.assign(structuredClone(DEFAULT_STATE.settings), remote.data.settings, keep);
    }
    SYNC_FROM_SETTINGS.forEach(k => { S.settings[k] = fromSettings[k]; });
    if (S.settings.place && !places().some(p => p.id === S.settings.place)) S.settings.place = null;   // deleted on another phone
    if (remote && remote.data && remote.data.aiKey && !aiKey()) { try { localStorage.setItem('ironlog.anthropicKey', remote.data.aiKey); } catch (e) { /* no storage */ } }
    const settings = { ...S.settings }; SYNC_LOCAL_SETTINGS.forEach(k => delete settings[k]);
    const data = { ...syncLocalData(), settings, ...(meta.includeKey && aiKey() ? { aiKey: aiKey() } : {}) };
    fileId = await driveWrite(token, fileId, { format: SYNC_FORMAT, v: SYNC_V, app: APP_VERSION, savedAt: now, data, tomb: m.tomb });
    setSyncMeta({ ...syncMeta(), connected: true, fileId, lastSyncAt: now, known: syncKnown(data) });
    try {   // the readable summary never fails a sync
      const sid = await driveWriteNamed(token, syncMeta().summaryId, SYNC_SUMMARY, 'text/markdown', driveSummaryText());
      setSyncMeta({ ...syncMeta(), summaryId: sid });
    } catch (e) { /* next sync tries again */ }
    save(); bust();
    return { in: S.workouts.length - before.w + m.localDeletes.filter(d => d[0] === 'workouts').length, sessions: S.workouts.length, checkinsIn: S.checkins.length - before.c };
  } finally { syncBusy = false; }
}
/* Backup on the Done tap. Google's token lasts an hour and there's no server
   to renew it, so a sync can't run unseen later — but a tap is a user gesture,
   which lets the sign-in run. With consent already given it's usually a quick
   flash. Skipped if a sync finished in the last two minutes (autoSync on a
   live token already did it). */
export function finishBackup() {
  const m = syncMeta();
  if (!m.connected || m.autoFinish === false) return;
  if (m.lastSyncAt && Date.now() - m.lastSyncAt < 120e3) return;
  driveSync(true).then(r => { if (r) toast('Backed up to Drive', 'green'); }).catch(e => toast(`Backup didn't run — ${e.message || 'try Sync now in Settings'}`));
}
export function autoSync() {
  if (!syncMeta().connected || !driveTokenValid()) return;
  driveSync(false).then(r => { if (r) refreshSyncLine(); }).catch(() => { /* next manual sync will say */ });
}
export function relTime(ms) {
  const m = Math.round((Date.now() - ms) / 60000);
  return m < 1 ? 'just now' : m < 60 ? `${m} min ago` : m < 1440 ? `${Math.round(m / 60)} h ago` : relDay(iso(new Date(ms))).toLowerCase();
}
export function syncLine() {
  const m = syncMeta(), cid = driveClientId();
  return `<div id="stSync">
    ${!cid ? `<div class="sub" style="margin-bottom:8px">Drive backup isn't set up for this copy of Ironlog yet — it needs a Google client ID for this web address (Advanced, below).</div>`
      : m.connected ? `<div class="sub" style="margin-bottom:8px">✓ Connected. ${m.lastSyncAt ? `Last synced ${relTime(m.lastSyncAt)}.` : ''} Your log is in <b>${esc(SYNC_FILE)}</b> in your Drive.</div>
        <div class="row" style="gap:8px;margin-bottom:8px"><button class="btn sm primary grow" id="stSyncNow">Sync now</button><button class="btn sm ghost" id="stSyncOff">Disconnect</button></div>`
      : `<div class="sub" style="margin-bottom:8px">Keeps a copy of your log in your own Google Drive and merges it between phones. Ironlog can only see the one file it makes there — nothing else in your Drive — and nothing goes to any Ironlog server.</div>
        <button class="btn sm primary wide" id="stSyncNow" style="margin-bottom:8px">Connect Google Drive</button>`}
    ${cid ? `<label class="row" style="gap:8px;align-items:center;margin-bottom:8px"><input type="checkbox" id="stSyncKey" ${m.includeKey ? 'checked' : ''} style="width:auto">
      <span class="sub">Include my AI key in the backup</span></label>` : ''}
    ${m.connected ? `<label class="row" style="gap:8px;align-items:center;margin-bottom:8px"><input type="checkbox" id="stSyncFinish" ${m.autoFinish !== false ? 'checked' : ''} style="width:auto">
      <span class="sub">Back up when I tap Done after a session (Google may flash its sign-in)</span></label>` : ''}
    <details style="margin-bottom:6px"><summary class="sub">Advanced: Google client ID</summary>
      <input id="stClientId" aria-label="Google client ID" value="${esc(m.clientId || '')}" placeholder="${esc(GOOGLE_CLIENT_ID || '….apps.googleusercontent.com')}" autocomplete="off" spellcheck="false" style="margin-top:6px">
      <div class="sub" style="margin-top:4px">Only needed if this copy wasn't built with one. Setup: r&amp;d/specs/drive-sync-spec.md.</div></details>
  </div>`;
}
let syncHost = null;
export function refreshSyncLine(bg) {
  if (bg) syncHost = bg;
  const host = syncHost && document.body.contains(syncHost) ? syncHost : null;
  const el = host && $('#stSync', host);
  if (!el) return;
  el.outerHTML = syncLine();
  const now = $('#stSyncNow', host), off = $('#stSyncOff', host), key = $('#stSyncKey', host), cid = $('#stClientId', host);
  if (cid) cid.onchange = () => { const v = cid.value.trim(); const m = syncMeta(); if (v) m.clientId = v; else delete m.clientId; setSyncMeta(m); refreshSyncLine(); };
  if (key) key.onchange = () => setSyncMeta({ ...syncMeta(), includeKey: key.checked });
  const fin = $('#stSyncFinish', host);
  if (fin) fin.onchange = () => setSyncMeta({ ...syncMeta(), autoFinish: fin.checked });
  if (off) off.onclick = () => confirmDlg('Disconnect Google Drive? The backup file stays in your Drive; this phone just stops syncing to it.',
    async () => { await driveDisconnect(); refreshSyncLine(); toast('Disconnected'); }, 'Disconnect');
  if (now) now.onclick = async () => {
    now.disabled = true; now.textContent = 'Syncing…';
    try {
      const r = await driveSync(true);
      if (r) toast(r.in > 0 ? `Synced · ${r.in} session${r.in === 1 ? '' : 's'} came in` : 'Synced', 'green');
      render();
    } catch (e) { toast(e.message || 'Sync failed'); }
    refreshSyncLine();
  };
}
